mapper.select:
SELECT * FROM outbox_event WHERE tenant_id = #{tenantId} AND aggregate_id = #{id}
    AND aggregate_type = 'cloudflow-service-oa' AND event_type = 'CONTRACT_PERFORMANCE_CHANGED'
ORDER BY id DESC LIMIT 1

SELECT end_time FROM wf_process_instance WHERE tenant_id = #{contract.tenantId}
    AND instance_id = #{contract.instanceId} AND business_key = CONCAT('CONTRACT:', #{contract.contractId})
    AND process_def_key = 'biz_contract' AND status IN ('PASSED', 'AUTO_PASSED') AND deleted = 0

mapper.update:
UPDATE oa_contract SET start_date = #{contract.startDate}, version = version + 1,
    update_by = #{contract.updateBy}, update_time = #{contract.updateTime}
WHERE tenant_id = #{contract.tenantId} AND contract_id = #{contract.contractId}
    AND deleted = 0 AND version = #{contract.version} AND start_date IS NULL

