SELECT event_id, amount, currency, team_version, source_snapshot FROM crm_deal_event
WHERE tenant_id = #{tenantId} AND biz_type = 'CONTRACT' AND biz_id = #{id}
    AND event_type = 'CONTRACT' AND event_key = #{eventKey} AND baseline_flag = 0
